-- Agregados: catálogos por NOMBRE (no por id) y fechas = hoy (hora de México) − días
WITH hoy AS (SELECT (now() AT TIME ZONE 'America/Mexico_City')::date AS d)
INSERT INTO agregados (cliente_id, proveedor_id, contrarrecibo, nur, cpt, descripcion, tipo_servicio_id, solicitante_id,
