       hoy.d - v.dias_sol, CASE WHEN v.dias_carga IS NULL THEN NULL ELSE hoy.d - v.dias_carga END, v.estatus, v.notas,
       EXTRACT(YEAR FROM hoy.d - v.dias_sol)::smallint, v.origen, v.fila_excel, v.revision, v.motivo_revision,
       v.eliminado, v.motivo_baja, v.solicitado, CASE WHEN v.solicitado THEN (hoy.d - v.dias_sol + 2) + time '10:00' END,
